<?php
declare(strict_types=1);
require_once __DIR__.'/includes/auth.php';
require_once __DIR__.'/includes/discom_requests.php';
require_login_any_role(discom_allowed_roles());
$actor=current_user()?:[]; if(!discom_authorized($actor)){http_response_code(403);exit('Access denied.');}
$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
if(isset($_GET['artifact'],$_GET['id'])){$r=discom_get((string)$_GET['id']);$type=(string)$_GET['artifact'];if(!$r||!in_array($type,['pdf','csv'],true)){http_response_code(404);exit('Not found.');}$name=(string)($r['artifacts'][$type]??'');$path=discom_artifacts_dir().'/'.basename($name);if(!is_file($path)){http_response_code(404);exit('Not found.');}header('X-Content-Type-Options: nosniff');header('Cache-Control: private, no-store');header('Content-Type: '.($type==='pdf'?'application/pdf':'text/csv; charset=UTF-8'));header('Content-Disposition: attachment; filename="'.basename($name).'"');readfile($path);exit;}
$validation=null;$created=null;$selected=array_values(array_filter(array_map('strval',(array)($_POST['quotation_ids']??[]))));
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??null)){http_response_code(403);$error='Security validation failed.';}else{$action=(string)($_POST['action']??'');if(in_array($action,['review','create'],true)){$validation=discom_validate_ids($selected,$actor);if($action==='create'){$created=discom_create($selected,$_POST,$actor);if(empty($created['ok']))$error=(string)($created['error']??'Unable to create request.');}}elseif($action==='mark_shared'){$r=discom_get((string)($_POST['id']??''));if($r)$created=discom_mark_whatsapp_shared($r,$actor);}elseif($action==='transition'){$r=discom_get((string)($_POST['id']??''));if($r)$created=discom_transition($r,(string)($_POST['status']??''),$actor,(string)($_POST['reason']??''));}}}
