?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DISCOM Requests</title><link rel="stylesheet" href="layout-styles.css"><style>body{font-family:system-ui;margin:0;background:#f4f7fb;color:#172033}main{max-width:1400px;margin:auto;padding:20px}.card{background:#fff;border:1px solid #dce3ed;border-radius:12px;padding:18px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}label{display:grid;gap:5px}input,select,textarea,button{font:inherit;padding:9px}textarea{min-height:90px}.btn{display:inline-block;background:#075985;color:#fff;border:0;border-radius:7px;padding:9px 12px;text-decoration:none}.secondary{background:#e5edf5;color:#172033}.warn{color:#9a3412}.table-wrap,.discom-table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;table-layout:auto}th,td{padding:9px;border:1px solid #dce3ed;text-align:left;overflow-wrap:anywhere;max-width:28rem}.badge{padding:4px 8px;border-radius:99px;background:#e0f2fe;white-space:nowrap}@media(max-width:700px){.outgoing-table thead{display:none}.outgoing-table tr,.outgoing-table td{display:block}.outgoing-table tr{margin:8px;border:1px solid #ddd}}</style></head><body><main><h1>DISCOM Requests</h1><p><a href="admin-documents.php?tab=accepted_customers">Accepted</a> · <a href="admin-documents.php?tab=completed_customers">Completed</a></p><?php if(isset($error)):?><p class="card warn" role="alert"><?=$h($error)?></p><?php endif;?>
<?php if($validation):?><section class="card"><h2>Review selection</h2><p><?=count($validation['complete'])?> complete; <?=count($validation['blocked'])+count($validation['invalid'])?> blocked. Incomplete projects are excluded; complete projects can continue.</p><?php foreach(array_merge($validation['complete'],$validation['blocked']) as $id=>$v):?><article><strong><?=$h($v['data']['customer_name']?:$id)?></strong> — <?=$h($v['data']['quotation_reference'])?> <span class="badge"><?=empty($v['complete'])?'Blocked':'Complete'?></span><?php if(empty($v['complete'])):?><ul><?php foreach($v['issues'] as $issue):?><li><?=$h($issue)?></li><?php endforeach;?></ul><a href="admin-customers.php?q=<?=$h(urlencode($v['customer_mobile']))?>">Open Customer User</a><?php endif;?></article><?php endforeach;?><form method="post"><input type="hidden" name="csrf_token" value="<?=$h($_SESSION['csrf_token']??'')?>"><?php foreach(array_keys($validation['complete']) as $id):?><input type="hidden" name="quotation_ids[]" value="<?=$h($id)?>"><?php endforeach;?><div class="grid"><label>Request type<select name="request_type"><option value="installation_inspection">Installation inspection</option><option value="net_metering">Net metering</option><option value="both" selected>Both</option></select></label><label>Communication<select name="communication"><option>Email</option><option>WhatsApp</option><option>Both</option></select></label><label>Request date<input type="date" name="request_date" value="<?=date('Y-m-d')?>"></label><label>Requested timeline<input name="requested_timeline" placeholder="Target only; not guaranteed"></label><label>Follow-up date<input type="date" name="follow_up_date"></label><label>Subject<input name="subject" value="Solar installation inspection / net-metering request"></label><label>Signatory<input name="signatory"></label><label>Introduction / body<textarea name="message">Please arrange the requested DISCOM action for the projects listed below.</textarea></label><label>Email body<textarea name="email_body">Please find the project details below and the signed request attached.</textarea></label><label>Internal notes<textarea name="internal_notes"></textarea></label></div><fieldset><legend>Optional outgoing columns</legend><?php foreach(['registered_mobile','installed_capacity','address','quotation_reference'] as $c):?><label style="display:inline-block;margin-right:12px"><input type="checkbox" name="columns[]" value="<?=$h($c)?>"> <?=$h(discom_column_labels()[$c])?></label><?php endforeach;?><?php foreach(discom_default_columns() as $c):?><input type="hidden" name="columns[]" value="<?=$h($c)?>"><?php endforeach;?></fieldset><?php if(count(discom_group_projects($validation['complete']))>1):?><p class="warn"><strong>Warning:</strong> projects span multiple Division + Subdivision groups. Separate requests are required unless you explicitly combine them.</p><label><input type="checkbox" name="combine_groups" value="1"> Combine groups after reviewing this warning</label><?php endif;?><button class="btn" name="action" value="create">Create DISCOM request</button> <button class="btn secondary" name="action" value="review">Refresh validation</button></form></section><?php endif;?>
<?php if(!empty($created['ok'])):$r=$created['request'];?><section class="card"><h2><?=$h($r['display_number'])?> created</h2><?=discom_html_table($r['snapshot'],$r['columns'])?><p><a class="btn" href="?id=<?=$h(urlencode($r['id']))?>&artifact=pdf">Download PDF</a> <a class="btn secondary" href="?id=<?=$h(urlencode($r['id']))?>&artifact=csv">CSV export</a></p><textarea id="wa-message" readonly><?=$h(discom_whatsapp_message($r))?></textarea><p><button class="btn secondary" onclick="navigator.clipboard.writeText(document.getElementById('wa-message').value)">Copy message</button> <button class="btn secondary" onclick="navigator.share&&navigator.share({title:'DISCOM request',text:document.getElementById('wa-message').value})">Share package</button> <a class="btn secondary" target="_blank" rel="noopener" href="https://web.whatsapp.com/">Open WhatsApp / WhatsApp Web</a></p><p>No customer details are placed in the WhatsApp URL, and an ordinary URL cannot target a group automatically. Opening WhatsApp does not mark this shared.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=$h($_SESSION['csrf_token']??'')?>"><input type="hidden" name="id" value="<?=$h($r['id'])?>"><button class="btn" name="action" value="mark_shared">Mark shared</button></form></section><?php endif;?>
<section class="card"><h2>Requests workspace</h2><form class="grid"><label>Batch, customer, application or account<input name="q" value="<?=$h($q)?>"></label><label>Division<input name="division" value="<?=$h($_GET['division']??'')?>"></label><label>Status<select name="status"><option value="">All</option><?php foreach(['Draft','Ready','Sent','Acknowledged','Inspection Scheduled','Inspection Completed','Net Metering Pending','Net Meter Installed','Closed','Cancelled'] as $s):?><option <?=$status===$s?'selected':''?>><?=$h($s)?></option><?php endforeach;?></select></label><button class="btn">Search</button></form><div class="table-wrap"><table><thead><tr><th>Batch</th><th>Group / projects</th><th>Type</th><th>Channels</th><th>Status</th><th>Dates</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$h($r['display_number'])?></td><td><?=$h($r['division'])?> / <?=$h($r['subdivision'])?><br><?=count($r['quotation_ids'])?> projects</td><td><?=$h(str_replace('_',' ',$r['request_type']))?></td><td>Email: <?=$h($r['channels']['email']['status']??'')?>; WhatsApp: <?=$h($r['channels']['whatsapp']['status']??'')?></td><td><span class="badge"><?=$h($r['status'])?></span></td><td>Created <?=$h($r['created_at'])?><br>Follow-up target <?=$h($r['follow_up_date']?:'—')?></td><td><a href="?id=<?=$h(urlencode($r['id']))?>&artifact=pdf">PDF</a> · <a href="?id=<?=$h(urlencode($r['id']))?>&artifact=csv">CSV</a><?php foreach($r['quotation_ids'] as $id):?><br><a href="admin-documents.php?tab=accepted_customers&view=<?=$h(urlencode($id))?>">Open project</a><?php endforeach;?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7">No requests found.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
